export const AffixById = Object.fromEntries(Affixs.map(e => [e.id, e]));
export const AffixGroupByAvailOn = Affixs.reduce((acc, e) => {
    if (e.availOn != null) {
        let arr = e.availOn;
        if (!Array.isArray(arr)) { arr = [arr]; }
        arr.forEach(group => {
            if (!acc[group]) {
                acc[group] = [];
            }
            acc[group].push(e);
        })
    }
    return acc;
}, {})
